let storageBusy=false;
function storagePanel(){return `<div class="panel"><h2>Armazenamento na hospedagem</h2><p>Biblioteca, empréstimos, documentos gerados e arquivos da APP ficam no servidor. As alterações são compartilhadas automaticamente entre os computadores.</p><div id="sharedStatus" class="data-status" role="status">${esc(sharedStatus)}</div><div class="actions" style="justify-content:flex-start;flex-wrap:wrap"><button onclick="retryShared()">Atualizar / tentar salvar novamente</button></div></div><div class="panel"><h2>Backup completo e restauração</h2><p>Baixe todos os registros e anexos em um único arquivo. Para mudar de hospedagem, instale este site no novo servidor e restaure o backup.</p><div class="actions" style="justify-content:flex-start;flex-wrap:wrap"><button class="primary" onclick="downloadCompleteBackup()">Baixar backup completo</button><button onclick="document.getElementById('completeBackupInput').click()">Restaurar backup completo</button></div><input hidden id="completeBackupInput" type="file" accept=".json" onchange="restoreCompleteBackup(this)"><p id="backupProgress" role="status"></p></div><div class="panel"><h2>Recuperar registros deste computador</h2><p>Registros antigos que existiam apenas neste navegador são preservados separadamente. A recuperação acrescenta registros ausentes sem substituir registros do servidor.</p><div class="actions" style="justify-content:flex-start;flex-wrap:wrap"><button onclick="recoverLocalDraft()">Recuperar registros antigos</button><button onclick="exportLocalDraft()">Baixar rascunho preservado</button><button onclick="useServerVersion()">Usar versão do servidor</button><button onclick="importDataFile()">Importar JSON antigo</button></div></div>`}
async function storageRequest(path,body){const response=await fetch('/api/storage/'+path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});const result=await response.json();if(!response.ok)throw Error(result.error||'Falha no armazenamento.');return result}
function backupProgress(message){const el=document.getElementById('backupProgress');if(el)el.textContent=message}
function downloadJson(data,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),60000)}
async function sha256(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('')}
function encodeBytes(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s)}
window.downloadCompleteBackup=async()=>{if(storageBusy)return;storageBusy=true;try{await sharedQueue;if(localStorage.getItem('cei-shared-dirty')==='1')throw Error('Há alterações pendentes neste computador. Tente salvar novamente antes de baixar o backup.');backupProgress('Preparando registros e anexos…');const backup=await storageRequest('backup');for(let i=0;i<backup.archive.files.length;i++){const file=backup.archive.files[i];backupProgress(`Incluindo anexo ${i+1} de ${backup.archive.files.length}…`);const response=await fetch('/api/storage/backup/file?'+new URLSearchParams({snapshot:backup.snapshot,id:file.recordId,field:file.field}),{cache:'no-store'});if(!response.ok)throw Error((await response.json()).error);const bytes=new Uint8Array(await response.arrayBuffer());file.size=bytes.length;file.sha256=await sha256(bytes);if(file.sha256!==response.headers.get('X-Backup-SHA256'))throw Error('Anexo recebido com erro. Reinicie o backup.');file.base64=encodeBytes(bytes)}if((await storageRequest('backup/check')).snapshot!==backup.snapshot)throw Error('A base mudou durante o backup. Baixe novamente para incluir as alterações.');delete backup.snapshot;downloadJson(backup,'cei-backup-completo-'+new Date().toISOString().slice(0,10)+'.json');backupProgress(`Backup completo: ${backup.archive.records.filter(r=>!r.internal).length} documentos da APP e ${backup.archive.files.length} anexos, incluindo fotografias dos formulários e todos os registros.`)}catch(error){backupProgress('Backup não concluído: '+error.message);alert(error.message)}finally{storageBusy=false}};
window.restoreCompleteBackup=async input=>{if(storageBusy)return;const file=input.files?.[0];if(!file)return;storageBusy=true;try{const backup=JSON.parse(await file.text());if(backup.format!=='cei-admin-complete-backup'||backup.version!==2||!backup.state||!Array.isArray(backup.archive?.files))throw Error('Arquivo não reconhecido como backup completo.');backupProgress('Conferindo os anexos do backup…');for(const f of backup.archive.files){const bytes=Uint8Array.from(atob(f.base64||''),c=>c.charCodeAt(0));if(bytes.length!==f.size||await sha256(bytes)!==f.sha256)throw Error('Backup incompleto ou anexo corrompido. Nenhum dado foi substituído.')}if(!confirm(`Restaurar backup de ${new Date(backup.createdAt).toLocaleString('pt-BR')}?\n${sharedSummary(backup.state)}\n${backup.archive.records.filter(r=>!r.internal).length} documentos da APP e ${backup.archive.files.length} anexos.\n\nA base compartilhada de todos os usuários será substituída. Baixe antes um backup da base atual se precisar conservá-la.`))return;await sharedQueue;if(localStorage.getItem('cei-shared-dirty')==='1')throw Error('Salve ou resolva as alterações pendentes antes de restaurar.');const manifest={...backup,archive:{records:backup.archive.records,files:backup.archive.files.map(({base64,...f})=>f)}};const job=await storageRequest('restore/start',manifest);for(let i=0;i<backup.archive.files.length;i++){backupProgress(`Enviando anexo ${i+1} de ${backup.archive.files.length}…`);const bytes=Uint8Array.from(atob(backup.archive.files[i].base64),c=>c.charCodeAt(0));const response=await fetch(`/api/storage/restore/${job.id}/file?index=${i}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:bytes});if(!response.ok)throw Error((await response.json()).error)}backupProgress('Conferindo e ativando a base restaurada…');await storageRequest(`restore/${job.id}/commit`,{});await adoptShared(await sharedRequest('GET'));appArchiveLoaded=false;render();backupProgress('Restauração concluída. Os registros estão disponíveis para todos.')}catch(error){backupProgress('Restauração não concluída: '+error.message);alert(error.message)}finally{storageBusy=false;input.value=''}};
